type HintOption = { label?: string; value?: string };

export function hintExplanation(
  hint: unknown,
  options: readonly HintOption[],
  customLabel: string,
): string {
  const tag = hint && typeof hint === 'object' ? (hint as HintOption) : null;
  const key = String(tag?.value ?? tag?.label ?? hint).toUpperCase();
  const option = (options || []).find((item) =>
    [item.value, item.label].some(
      (value) => value != null && value.toUpperCase() === key,
    ),
  );
  return option?.label ?? customLabel;
}

/** Preview data is deliberately tolerant of evidence missing on older documents. */
export interface MappingDecision {
  row_id?: string | number | null;
  column_index?: string | number | null;
  raw_name?: string | null;
  raw_path?: string | null;
  raw_key_status?: string | null;
  destination?: string | null;
  basis?: string | null;
  mapping_source?: string | null;
  hidden_by?: unknown;
  discarded_reason?: string | null;
  collision?: unknown;
  location?: unknown;
}
export interface Evidence {
  processing_run_id?: string;
  preview?: boolean;
  effective_hints?: {
    submitted?: string;
    kind?: string;
    schema_key?: string | null;
    dropped_reason?: string | null;
    explanation?: string;
  }[];
  selected_training?: {
    status?: string;
    rule_id?: string | null;
    ambiguity?: {
      status?: string;
      other_rule_ids?: string[];
      truncated?: boolean;
    };
    [key: string]: unknown;
  } | null;
  column_policy?: { state?: string; reason?: string; [key: string]: unknown };
  request_overrides_used?: boolean;
  [key: string]: unknown;
}
export interface TableCell {
  name?: string;
  content?: unknown;
  original_name?: string | null;
}
export interface TableRow {
  id?: string | number;
  is_deleted?: boolean;
  columns?: TableCell[] | Record<string, TableCell>;
}
export interface TableData {
  layout?: { column_name?: string; title?: string }[];
  rows?: TableRow[];
  mapping_decisions?: MappingDecision[];
  [key: string]: unknown;
}
export interface CellDiff {
  before: string | null;
  after: string | null;
  state: 'unchanged' | 'changed' | 'added' | 'missing';
  sourceBefore?: string;
  sourceAfter?: string;
  reassigned: boolean;
  reason?: string;
  decision?: MappingDecision;
}
export interface TableDiff {
  rows: {
    rowKey: string;
    status: 'matched' | 'added' | 'missing';
    matchedBy: 'position' | 'index';
    cells: Record<string, CellDiff>;
  }[];
  columns: { added: string[]; missing: string[] };
  columnNames: string[];
}
const value = (content: unknown): string | null =>
  content == null ? null : String(content).trim();
const cells = (row?: TableRow): Record<string, TableCell> =>
  Object.fromEntries(
    Object.entries(row?.columns || {}).map(([key, cell]) => [
      cell.name || key,
      cell,
    ]),
  );
const columnNames = (table: TableData, rows: TableRow[]): string[] => [
  ...new Set([
    ...(table.layout || [])
      .map((column) => column.column_name)
      .filter((name): name is string => !!name),
    ...rows.flatMap((row) => Object.keys(cells(row))),
  ]),
];
const position = (row: TableRow): string | null =>
  value(cells(row).POSITION?.content) || null;
const positions = (rows: TableRow[]): Map<string, number[]> => {
  const result = new Map<string, number[]>();
  rows.forEach((row, index) => {
    const key = position(row);
    if (key !== null) result.set(key, [...(result.get(key) || []), index]);
  });
  return result;
};

export function buildTableDiff(
  baseline: TableData,
  candidate: TableData,
  _evidence: Evidence,
): TableDiff {
  const beforeRows = (baseline.rows || []).filter((row) => !row.is_deleted);
  const afterRows = (candidate.rows || []).filter((row) => !row.is_deleted);
  const beforeColumns = columnNames(baseline, beforeRows);
  const afterColumns = columnNames(candidate, afterRows);
  const names = [...new Set([...beforeColumns, ...afterColumns])];
  const beforePositions = positions(beforeRows);
  const afterPositions = positions(afterRows);
  const matches = new Map<number, number>();
  const used = new Set<number>();
  const byPosition = new Set<number>();
  beforeRows.forEach((row, index) => {
    const key = position(row);
    if (
      key &&
      beforePositions.get(key)?.length === 1 &&
      afterPositions.get(key)?.length === 1
    ) {
      const other = afterPositions.get(key)![0];
      matches.set(index, other);
      used.add(other);
      byPosition.add(index);
    }
  });
  beforeRows.forEach((row, index) => {
    if (matches.has(index) || used.has(index) || !afterRows[index]) return;
    const a = position(row);
    const b = position(afterRows[index]);
    // Distinct, unambiguous positions represent missing/added rows, not edits.
    if (
      a &&
      b &&
      beforePositions.get(a)?.length === 1 &&
      afterPositions.get(b)?.length === 1 &&
      (afterPositions.get(a)?.length || 0) < 2 &&
      (beforePositions.get(b)?.length || 0) < 2
    )
      return;
    matches.set(index, index);
    used.add(index);
  });
  const pairs = beforeRows.map((row, index) => ({
    before: row,
    after: matches.has(index) ? afterRows[matches.get(index)!] : undefined,
    rowKey: `before:${index}`,
    matchedBy: byPosition.has(index)
      ? ('position' as const)
      : ('index' as const),
  }));
  const allPairs: {
    before?: TableRow;
    after?: TableRow;
    rowKey: string;
    matchedBy: 'position' | 'index';
  }[] = [...pairs];
  afterRows.forEach((row, index) => {
    if (!used.has(index))
      allPairs.push({
        after: row,
        rowKey: `after:${index}`,
        matchedBy: 'index',
      });
  });
  return {
    columnNames: names,
    columns: {
      added: afterColumns.filter((name) => !beforeColumns.includes(name)),
      missing: beforeColumns.filter((name) => !afterColumns.includes(name)),
    },
    rows: allPairs.map(({ before, after, rowKey, matchedBy }) => {
      const a = cells(before);
      const b = cells(after);
      return {
        rowKey,
        matchedBy,
        status: !before ? 'added' : !after ? 'missing' : 'matched',
        cells: Object.fromEntries(
          names.map((name) => {
            const beforeValue = value(a[name]?.content);
            const afterValue = value(b[name]?.content);
            const decision =
              after?.id == null
                ? undefined
                : candidate.mapping_decisions?.find(
                    (item) =>
                      item.row_id != null &&
                      String(item.row_id) === String(after.id) &&
                      item.destination === name,
                  );
            const sourceBefore = a[name]?.original_name || undefined;
            const sourceAfter = decision?.raw_name || undefined;
            const reason =
              !decision || decision.raw_key_status !== 'known'
                ? 'unknown'
                : [
                    decision.raw_name,
                    decision.raw_path,
                    decision.destination,
                    decision.basis,
                    decision.mapping_source,
                    decision.hidden_by == null
                      ? ''
                      : JSON.stringify(decision.hidden_by),
                    decision.discarded_reason,
                  ]
                    .filter(Boolean)
                    .join(' · ');
            return [
              name,
              {
                before: beforeValue,
                after: afterValue,
                state:
                  !a[name] && b[name]
                    ? 'added'
                    : a[name] && !b[name]
                      ? 'missing'
                      : beforeValue === afterValue
                        ? 'unchanged'
                        : 'changed',
                sourceBefore,
                sourceAfter,
                reassigned: !!(
                  sourceBefore &&
                  sourceAfter &&
                  sourceBefore !== sourceAfter
                ),
                reason,
                decision,
              } satisfies CellDiff,
            ];
          }),
        ),
      };
    }),
  };
}
