<template>
  <q-dialog
    v-model="open"
    :maximized="maximized"
    transition-show="slide-up"
    transition-hide="slide-down"
    @hide="close"
  >
    <q-card
      class="ai-explanation"
      :class="{ 'ai-explanation--max': maximized }"
      data-test="ai-explanation-dialog"
    >
      <q-card-section class="row items-center no-wrap ai-explanation-head">
        <div>
          <h2 class="text-h6 q-my-none">{{ $t('ai_explain_title') }}</h2>
          <p class="ai-explanation-sub q-mb-none" v-if="explanation">
            {{ explanation.filename || explanation.doc_id }} ·
            {{ explanation.table_name }}
          </p>
        </div>
        <q-space />
        <q-btn
          v-if="explanation"
          flat
          dense
          no-caps
          icon="open_in_new"
          :label="$t('ai_explain_open_page')"
          data-test="ai-explanation-open-page"
          class="q-mr-sm"
          @click="openPage"
        />
        <q-btn
          flat
          round
          dense
          :icon="maximized ? 'fullscreen_exit' : 'fullscreen'"
          :title="
            maximized
              ? $t('ai_explain_restore_size')
              : $t('ai_explain_maximize')
          "
          data-test="ai-explanation-maximize"
          @click="maximized = !maximized"
        />
        <q-btn
          flat
          round
          dense
          icon="close"
          data-test="ai-explanation-close"
          @click="close"
        />
      </q-card-section>

      <q-card-section v-if="loading" data-test="ai-explanation-loading">
        <q-spinner size="sm" class="q-mr-sm" />{{ $t('ai_explain_loading') }}
      </q-card-section>

      <q-card-section
        v-else-if="forbidden"
        class="ai-explanation-forbidden"
        :data-test="`ai-explanation-forbidden-${forbidden}`"
      >
        <q-icon name="lock" size="28px" color="warning" class="q-mb-sm" />
        <p class="q-mb-sm">
          {{
            forbidden === 'module_off'
              ? $t('ai_explain_module_required')
              : $t('ai_explain_no_access')
          }}
        </p>
        <q-btn
          v-if="forbidden === 'module_off'"
          no-caps
          color="primary"
          icon="tune"
          :label="$t('ai_explain_open_modules')"
          data-test="ai-explanation-open-modules"
          @click="openModules"
        />
      </q-card-section>

      <q-card-section v-else-if="error" data-test="ai-explanation-error">
        {{ $t('ai_explain_failed') }}
        <span class="ai-explanation-hint">{{ error }}</span>
      </q-card-section>

      <div
        v-else-if="explanation"
        class="ai-explanation-body"
        data-test="ai-explanation-body"
      >
        <AITableExplanationContent
          :explanation="explanation"
          :stages="stages"
          :advice="advice"
          :advice-loading="adviceLoading"
        />
      </div>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
/**
 * "Show" for the AI table (DOCB-14569): the explanation as a dialog.
 *
 * Opens full screen (the explanation is long; nobody should wonder whether
 * there is more below the fold), can be restored to a resizable window, and
 * offers the same content as its own page — with the document preview next
 * to it — via the header button. The content lives in
 * `AITableExplanationContent`; this component only frames it.
 */
import { defineComponent, type PropType } from 'vue';
import AITableExplanationContent from 'src/components/document/AITableExplanationContent.vue';
import type { PipelineStage } from 'src/services/analytics/PipelineExplanationService';
import type {
  TableExplanation,
  TableExplanationAdvice,
} from 'src/services/analytics/TableExplanationService';
import {
  MODULES_ROUTE,
  type ForbiddenReason,
} from 'src/components/document/tableExplanationAccess';

export default defineComponent({
  name: 'AITableExplanation',
  components: { AITableExplanationContent },
  props: {
    explanation: {
      type: Object as PropType<TableExplanation | null>,
      default: null,
    },
    /** The full pipeline stages (from `pipeline-explanation`), when loaded. */
    stages: { type: Array as PropType<PipelineStage[]>, default: () => [] },
    loading: { type: Boolean, default: false },
    error: { type: String, default: '' },
    /**
     * The API answered 403. `module_off`: the Analytics Dashboard module is
     * switched off for the organisation (an admin can activate it);
     * `no_access`: the module is on, this user's role was not granted the tab.
     */
    forbidden: {
      type: String as PropType<ForbiddenReason | ''>,
      default: '',
    },
    /** The KI-Advisor block (Nexus), loaded by the parent in a second request. */
    advice: {
      type: Object as PropType<TableExplanationAdvice | null>,
      default: null,
    },
    adviceLoading: { type: Boolean, default: false },
  },
  emits: ['close', 'open-page'],
  data() {
    // Full screen first: the explanation is long (steps, mapping, advice,
    // pipeline, run, columns) and a reader must never wonder whether there is
    // more below the fold. The header button restores a resizable window.
    return { open: true, closed: false, maximized: true };
  },
  methods: {
    close() {
      if (!this.open && this.closed) return;
      this.open = false;
      this.closed = true;
      this.$emit('close');
    },
    /** Where the Analytics Dashboard module is switched on (org admins). */
    openModules() {
      void this.$router.push(MODULES_ROUTE);
      this.close();
    },
    /** The same explanation as its own page, with the document preview beside it. */
    openPage() {
      if (!this.explanation) return;
      this.$emit('open-page', {
        docId: this.explanation.doc_id,
        tableName: this.explanation.table_name,
      });
      void this.$router.push({
        name: 'table-explanation',
        params: { id: this.explanation.doc_id },
        query: this.explanation.table_name
          ? { table: this.explanation.table_name }
          : {},
      });
      this.close();
    },
  },
});
</script>

