<template>
  <q-dialog v-model="open" @escape-key="discard" @hide="discard">
    <q-card
      class="ai-comparison"
      data-test="ai-preview-dialog"
      @keydown.esc.stop.prevent="discard"
    >
      <q-card-section>
        <h2 class="text-h6 q-my-none">{{ $t('ai_preview_test') }}</h2>
        <p>{{ $t('ai_preview_compared_with') }}</p>
        <p aria-live="polite" role="status">
          {{ $t('ai_preview_summary', summary) }}
          <span v-if="stale">{{ $t('ai_preview_stale') }}</span>
        </p>
      </q-card-section>
      <q-card-section class="comparison-scroll">
        <table>
          <thead>
            <tr>
              <th v-for="column in diff.columnNames" :key="column" scope="col">
                {{ column }}
                <span v-if="diff.columns.missing.includes(column)">{{
                  $t('ai_preview_state_missing')
                }}</span>
                <span v-if="diff.columns.added.includes(column)">{{
                  $t('ai_preview_state_added')
                }}</span>
              </th>
            </tr>
          </thead>
          <tbody>
            <tr
              v-for="row in diff.rows"
              :key="row.rowKey"
              :data-matched-by="row.matchedBy"
            >
              <td v-for="column in diff.columnNames" :key="column">
                <div>
                  {{ row.cells[column].before ?? '—' }} →
                  {{ row.cells[column].after ?? '—' }}
                </div>
                <span class="state-badge" :class="row.cells[column].state">{{
                  stateLabel(row.cells[column].state)
                }}</span>
                <span
                  v-if="row.cells[column].reassigned"
                  class="state-badge reassigned"
                  >{{ $t('ai_preview_state_reassigned') }}</span
                >
                <details
                  v-if="
                    row.cells[column].state !== 'unchanged' ||
                    row.cells[column].reassigned
                  "
                >
                  <summary
                    :data-test="`ai-preview-reason-${row.rowKey}-${column}`"
                  >
                    {{ $t('ai_preview_reason_title') }}
                    <q-tooltip>{{ reasonText(row.cells[column]) }}</q-tooltip>
                  </summary>
                  <div class="reason">{{ reasonText(row.cells[column]) }}</div>
                </details>
              </td>
            </tr>
          </tbody>
        </table>
        <details class="q-mt-md">
          <summary data-test="ai-preview-evidence">
            {{ $t('ai_preview_evidence_hints') }}
          </summary>
          <ul>
            <li
              v-for="(hint, index) in evidence.effective_hints || []"
              :key="index"
            >
              {{ hint.submitted }} · {{ hint.kind }} ·
              {{
                hint.explanation === 'custom hint'
                  ? $t('ai_hints_custom')
                  : hint.explanation
              }}
              <span v-if="hint.dropped_reason">
                · {{ hint.dropped_reason }}</span
              >
            </li>
          </ul>
          <h3 class="text-subtitle2">
            {{ $t('ai_preview_evidence_training') }}
          </h3>
          <div v-if="evidence.selected_training?.status === 'none'">
            {{ $t('ai_training_none') }}
          </div>
          <div v-else>
            {{ evidence.selected_training?.status || 'unknown' }}
            {{ evidence.selected_training?.rule_id }}
          </div>
          <div
            v-if="evidence.selected_training?.ambiguity?.status === 'ambiguous'"
          >
            {{ $t('ai_training_ambiguous') }}:
            {{
              evidence.selected_training.ambiguity.other_rule_ids?.join(', ')
            }}
            <span v-if="evidence.selected_training.ambiguity.truncated">…</span>
          </div>
          <div v-else-if="evidence.selected_training?.ambiguity?.status">
            {{ evidence.selected_training.ambiguity.status }}
          </div>
          <h3 class="text-subtitle2">{{ $t('ai_preview_evidence_policy') }}</h3>
          <div>
            {{ evidence.column_policy?.state || 'unknown' }}
            {{ evidence.column_policy?.reason }}
          </div>
          <h3 class="text-subtitle2">
            {{ $t('ai_preview_evidence_overrides') }}
          </h3>
          <div>{{ evidence.request_overrides_used ?? 'unknown' }}</div>
        </details>
      </q-card-section>
      <q-card-actions align="right">
        <q-btn
          flat
          autofocus
          data-test="ai-preview-discard"
          @click.stop="discard"
          >{{ $t('ai_preview_discard') }}</q-btn
        >
        <q-btn
          color="primary"
          data-test="ai-preview-apply"
          :disable="stale || applying"
          :disabled="stale || applying"
          :aria-disabled="stale || applying"
          :loading="applying"
          @click="apply"
          >{{ $t('ai_preview_apply') }}</q-btn
        >
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import {
  buildTableDiff,
  type CellDiff,
  type Evidence,
  type TableData,
} from './tableDiff';

export default defineComponent({
  name: 'AITableComparison',
  props: {
    baseline: { type: Object as PropType<TableData>, required: true },
    candidate: { type: Object as PropType<TableData>, required: true },
    evidence: { type: Object as PropType<Evidence>, default: () => ({}) },
    stale: { type: Boolean, default: false },
    applying: { type: Boolean, default: false },
  },
  emits: ['apply', 'discard'],
  data() {
    return { open: true, discardEmitted: false };
  },
  computed: {
    diff() {
      return buildTableDiff(this.baseline, this.candidate, this.evidence);
    },
    summary() {
      const cells = this.diff.rows.flatMap((row) => Object.values(row.cells));
      const reassigned = this.diff.columnNames.filter((column) =>
        this.diff.rows.some((row) => row.cells[column].reassigned),
      ).length;
      return {
        changed: cells.filter((cell) => cell.state !== 'unchanged').length,
        added: this.diff.columns.added.length,
        missing: this.diff.columns.missing.length,
        reassigned,
      };
    },
  },
  methods: {
    discard() {
      this.open = false;
      if (!this.discardEmitted) {
        this.discardEmitted = true;
        this.$emit('discard');
      }
    },
    apply() {
      if (!this.stale && !this.applying && this.open)
        this.$emit('apply', this.candidate);
    },
    stateLabel(state: CellDiff['state']) {
      switch (state) {
        case 'changed':
          return this.$t('ai_preview_state_changed');
        case 'added':
          return this.$t('ai_preview_state_added');
        case 'missing':
          return this.$t('ai_preview_state_missing');
        default:
          return this.$t('ai_preview_state_unchanged');
      }
    },
    reasonText(cell: CellDiff) {
      if (cell.reason === 'unknown' || !cell.decision)
        return this.$t('ai_preview_reason_unknown');
      const decision = cell.decision;
      const raw = [decision.raw_name, decision.raw_path]
        .filter(Boolean)
        .join(' · ');
      return [
        `AI: ${raw} → DocBits: ${decision.destination || '—'}`,
        decision.basis,
        decision.mapping_source,
        decision.hidden_by == null
          ? null
          : `hidden_by: ${JSON.stringify(decision.hidden_by)}`,
        decision.discarded_reason,
      ]
        .filter(Boolean)
        .join(' · ');
    },
  },
});
</script>

<style scoped>
.ai-comparison {
  width: 1100px;
  max-width: 95vw;
}
.comparison-scroll {
  overflow: auto;
  max-height: 65vh;
}
table {
  width: 100%;
  border-collapse: collapse;
}
th,
td {
  text-align: left;
  vertical-align: top;
  border: 1px solid #999;
  padding: 8px;
}
.state-badge {
  display: inline-block;
  border: 1px solid currentColor;
  border-radius: 4px;
  padding: 2px 5px;
  margin: 4px 4px 4px 0;
}
.changed {
  color: #854d0e;
  background: #fef9c3;
}
.added {
  color: #166534;
  background: #dcfce7;
}
.missing {
  color: #991b1b;
